#!/usr/bin/env python3
import math
from typing import Dict, Any
class VerilogGenerator:
    def __init__(self, config: Dict[str, Any]):
        self.cfg = config
        self.arch = config.get('architecture', 'single_layer')
        self.is_hidden = self.arch == 'hidden_snn' or 'weights_l1' in config
        self.num_inputs = config['num_inputs']
        self.num_classes = config['num_classes']
        self.threshold = config.get('threshold', 200)
        self.leak_shift = config.get('leak_shift', 3)
        self.max_steps = config.get('max_steps', 32)
        self.input_idx_width = max(1, (self.num_inputs - 1).bit_length())
        self.class_width = max(1, (self.num_classes - 1).bit_length())
        if self.is_hidden:
            self.num_hidden = config.get('num_hidden', 12)
            self.weights_l1 = config['weights_l1']
            self.biases_l1 = config.get('biases_l1', [0] * self.num_hidden)
            self.weights_l2 = config['weights_l2']
            self.biases_l2 = config.get('biases_l2', [0] * self.num_classes)
            self.hidden_idx_width = max(1, (self.num_hidden - 1).bit_length())
            self.total_mem_depth = self.num_inputs + self.num_hidden
            self.mem_addr_width = max(7, (self.total_mem_depth - 1).bit_length())
        else:
            self.weights = config['weights']
        self.is_streaming = self.num_inputs > 256
    def generate_snn_core(self) -> str:
        if self.is_streaming:
            return '`default_nettype none\n// Streaming SNN core integrated into top.v\nmodule snn_core;\nendmodule\n'
        elif self.is_hidden:
            return self._generate_snn_core_hidden()
        else:
            return self._generate_snn_core_single()
    def _generate_snn_core_hidden(self) -> str:
        num_bram = (self.num_hidden + 3) // 4
        inits_by_block = [[] for _ in range(num_bram)]
        for i in range(self.num_inputs):
            for b in range(num_bram):
                val = 0
                for sub in range(4):
                    h_idx = b * 4 + sub
                    if h_idx < self.num_hidden:
                        w = int(self.weights_l1[h_idx][i]) & 511
                        val |= w << sub * 9
                inits_by_block[b].append(f"        syn_mem_{b}[{i}] = 36'h{val:09X};")
        for j in range(self.num_hidden):
            row = self.num_inputs + j
            for b in range(num_bram):
                val = 0
                for sub in range(4):
                    c_idx = b * 4 + sub
                    if c_idx < self.num_classes:
                        w = int(self.weights_l2[c_idx][j]) & 511
                        val |= w << sub * 9
                inits_by_block[b].append(f"        syn_mem_{b}[{row}] = 36'h{val:09X};")
        mem_depth = 256 if self.total_mem_depth <= 256 else 512
        mem_decls = []
        mem_reads = []
        for b in range(num_bram):
            mem_decls.append(f'    (* ram_style = "block" *) reg [35:0] syn_mem_{b} [0:{mem_depth - 1}];')
            mem_decls.append(f'    reg [35:0] syn_r{b};')
            mem_reads.append(f'        syn_r{b} <= syn_mem_{b}[mem_addr];')
        all_inits = []
        for b in range(num_bram):
            all_inits.extend(inits_by_block[b])
        mem_decls_str = '\n'.join(mem_decls)
        mem_reads_str = '\n'.join(mem_reads)
        mem_inits_str = '\n'.join(all_inits)
        w_l1_wires = []
        for h in range(self.num_hidden):
            b = h // 4
            sub = h % 4
            off = sub * 9
            w_l1_wires.append(f'    assign w_l1[{h}] = {{{{1{{syn_r{b}[{off + 8}]}}}}, syn_r{b}[{off + 8}:{off}]}};')
        w_l1_str = '\n'.join(w_l1_wires)
        w_l2_wires = []
        for c in range(self.num_classes):
            b = c // 4
            sub = c % 4
            off = sub * 9
            w_l2_wires.append(f'    assign w_l2[{c}] = {{{{1{{syn_r{b}[{off + 8}]}}}}, syn_r{b}[{off + 8}:{off}]}};')
        w_l2_str = '\n'.join(w_l2_wires)
        b1_loads = []
        for k in range(self.num_hidden):
            bv = int(self.biases_l1[k])
            b_str = f"10'sd{bv}" if bv >= 0 else f"-10'sd{abs(bv)}"
            b1_loads.append(f'                    v_mem[{k}] <= {b_str};')
        b1_loads_str = '\n'.join(b1_loads)
        b2_loads = []
        for c in range(self.num_classes):
            bv = int(self.biases_l2[c])
            b_str = f"10'sd{bv}" if bv >= 0 else f"-10'sd{abs(bv)}"
            b2_loads.append(f'                    v_mem[{c}] <= {b_str};')
        b2_loads_str = '\n'.join(b2_loads)
        pe_lines = [f"        if (out_spikes[0]) pe_class = {self.class_width}'d0;"]
        for k in range(1, self.num_classes):
            pe_lines.append(f"        else if (out_spikes[{k}]) pe_class = {self.class_width}'d{k};")
        pe_lines.append(f"        else pe_class = {self.class_width}'d0;")
        pe_str = '\n'.join(pe_lines)
        step_width = max(6, (self.num_inputs + 2).bit_length())
        code = f"`default_nettype none\n\n// Auto-generated 2-Layer Time-Multiplexed SNN Core\n// Inputs: {self.num_inputs}, Hidden: {self.num_hidden}, Classes: {self.num_classes}\n// BSRAM Blocks: {num_bram}, Max TTFS Steps: {self.max_steps}\n// Featuring cycle-accurate 1-cycle BRAM pipeline synchronization.\n\nmodule snn_core #(\n    parameter integer NUM_INPUTS    = {self.num_inputs},\n    parameter integer NUM_HIDDEN    = {self.num_hidden},\n    parameter integer NUM_CLASSES   = {self.num_classes},\n    parameter integer MAX_STEPS     = {self.max_steps},\n    parameter signed [9:0] THRESHOLD = 10'sd{self.threshold},\n    parameter integer LEAK_SHIFT    = {self.leak_shift}\n)(\n    input  wire                     clk,\n    input  wire                     rst_n,\n    input  wire                     sim_start,\n    input  wire [NUM_INPUTS-1:0]    pixels,\n    output reg                      done,\n    output reg  [{self.class_width - 1}:0]               best_class,\n    output reg  [5:0]               ttfs_step\n);\n\n    // 1. Dual-Layer Synaptic Memory ({num_bram} Gowin BSRAM blocks)\n{mem_decls_str}\n    reg [{self.mem_addr_width - 1}:0] mem_addr;\n\n    initial begin\n{mem_inits_str}\n    end\n\n    always @(posedge clk) begin\n{mem_reads_str}\n    end\n\n    // Synaptic Weight Slicers\n    wire signed [9:0] w_l1 [0:{self.num_hidden - 1}];\n{w_l1_str}\n\n    wire signed [9:0] w_l2 [0:{self.num_classes - 1}];\n{w_l2_str}\n\n    // 2. Time-Multiplexed Neuromorphic ALUs ({self.num_hidden} units)\n    reg signed [9:0] v_mem [0:{self.num_hidden - 1}];\n    reg [{self.num_hidden - 1}:0] h_spikes;\n\n    // 3. Pipeline Alignment Registers (Synchronized to BRAM read latency)\n    reg pixel_pipe;\n    reg l1_valid;\n    reg spike_pipe;\n    reg l2_valid;\n\n    localparam [2:0]\n        ST_IDLE      = 3'd0,\n        ST_L1_LOAD   = 3'd1,\n        ST_L1_ACC    = 3'd2,\n        ST_L1_SPIKE  = 3'd3,\n        ST_L2_ACC    = 3'd4,\n        ST_TTFS_RAMP = 3'd5;\n\n    reg [2:0] state;\n    reg [{step_width - 1}:0] step_cnt;\n\n    // Output threshold detection: v >= 256 (positive sign bit & bit 8 == 1)\n    wire [{self.num_classes - 1}:0] out_spikes;\n    genvar g;\n    generate\n        for (g = 0; g < {self.num_classes}; g = g + 1) begin : gen_out_spikes\n            assign out_spikes[g] = (~v_mem[g][9]) & v_mem[g][8];\n        end\n    endgenerate\n\n    // Priority encoder\n    reg [{self.class_width - 1}:0] pe_class;\n    always @(*) begin\n{pe_str}\n    end\n\n    integer k;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state      <= ST_IDLE;\n            mem_addr   <= {self.mem_addr_width}'d0;\n            step_cnt   <= {step_width}'d0;\n            done       <= 1'b0;\n            best_class <= {self.class_width}'d0;\n            ttfs_step  <= 6'd0;\n            h_spikes   <= {self.num_hidden}'d0;\n            pixel_pipe <= 1'b0;\n            l1_valid   <= 1'b0;\n            spike_pipe <= 1'b0;\n            l2_valid   <= 1'b0;\n            for (k = 0; k < {self.num_hidden}; k = k + 1) v_mem[k] <= 10'sd0;\n        end else begin\n            done <= 1'b0;\n\n            // Pipeline Alignment: Latch pixel/spike at same cycle address is presented to BRAM\n            if (state == ST_L1_ACC) begin\n                pixel_pipe <= pixels[mem_addr];\n                l1_valid   <= 1'b1;\n            end else begin\n                pixel_pipe <= 1'b0;\n                l1_valid   <= 1'b0;\n            end\n\n            if (state == ST_L2_ACC) begin\n                spike_pipe <= h_spikes[mem_addr - {self.mem_addr_width}'d{self.num_inputs}];\n                l2_valid   <= 1'b1;\n            end else begin\n                spike_pipe <= 1'b0;\n                l2_valid   <= 1'b0;\n            end\n\n            // Accumulate on pipeline arrival\n            if (l1_valid && pixel_pipe) begin\n                for (k = 0; k < {self.num_hidden}; k = k + 1) begin\n                    v_mem[k] <= v_mem[k] + w_l1[k];\n                end\n            end\n\n            if (l2_valid && spike_pipe) begin\n                for (k = 0; k < {self.num_classes}; k = k + 1) begin\n                    v_mem[k] <= v_mem[k] + w_l2[k];\n                end\n            end\n\n            case (state)\n                ST_IDLE: begin\n                    if (sim_start) begin\n                        state    <= ST_L1_LOAD;\n                        mem_addr <= {self.mem_addr_width}'d0;\n                        step_cnt <= {step_width}'d0;\n                    end\n                end\n\n                ST_L1_LOAD: begin\n                    // Load Layer 1 biases\n{b1_loads_str}\n                    state    <= ST_L1_ACC;\n                    mem_addr <= {self.mem_addr_width}'d0;\n                    step_cnt <= {step_width}'d0;\n                end\n\n                ST_L1_ACC: begin\n                    if (mem_addr < {self.mem_addr_width}'d{self.num_inputs - 1}) begin\n                        mem_addr <= mem_addr + 1'b1;\n                    end else begin\n                        mem_addr <= {self.mem_addr_width}'d{self.num_inputs}; // Prepare L2 read\n                    end\n\n                    // step_cnt waits 1 extra cycle to allow last BRAM output to be accumulated\n                    if (step_cnt == {step_width}'d{self.num_inputs}) begin\n                        state    <= ST_L1_SPIKE;\n                        step_cnt <= {step_width}'d0;\n                    end else begin\n                        step_cnt <= step_cnt + 1'b1;\n                    end\n                end\n\n                ST_L1_SPIKE: begin\n                    // Evaluate 1-bit hidden action potentials: v >= 0\n                    for (k = 0; k < {self.num_hidden}; k = k + 1) begin\n                        h_spikes[k] <= ~v_mem[k][9];\n                    end\n                    // Reload output biases into units 0..{self.num_classes - 1}\n{b2_loads_str}\n                    state    <= ST_L2_ACC;\n                    mem_addr <= {self.mem_addr_width}'d{self.num_inputs};\n                    step_cnt <= {step_width}'d0;\n                end\n\n                ST_L2_ACC: begin\n                    if (mem_addr < {self.mem_addr_width}'d{self.total_mem_depth - 1}) begin\n                        mem_addr <= mem_addr + 1'b1;\n                    end\n\n                    // step_cnt waits 1 extra cycle for last L2 BRAM read\n                    if (step_cnt == {step_width}'d{self.num_hidden}) begin\n                        state    <= ST_TTFS_RAMP;\n                        step_cnt <= {step_width}'d0;\n                    end else begin\n                        step_cnt <= step_cnt + 1'b1;\n                    end\n                end\n\n                ST_TTFS_RAMP: begin\n                    // Ramp potential +16 each step until first spike\n                    for (k = 0; k < {self.num_classes}; k = k + 1) begin\n                        v_mem[k] <= v_mem[k] + 10'sd16;\n                    end\n\n                    if (|out_spikes) begin\n                        done       <= 1'b1;\n                        best_class <= pe_class;\n                        ttfs_step  <= step_cnt[5:0];\n                        state      <= ST_IDLE;\n                    end else if (step_cnt >= {step_width}'d{self.max_steps - 1}) begin\n                        done       <= 1'b1;\n                        best_class <= pe_class;\n                        ttfs_step  <= step_cnt[5:0];\n                        state      <= ST_IDLE;\n                    end else begin\n                        step_cnt <= step_cnt + 1'b1;\n                    end\n                end\n            endcase\n        end\n    end\n\nendmodule\n"
        return code
    def _generate_snn_core_single(self) -> str:
        blocks = []
        c_idx = 0
        while c_idx < self.num_classes:
            chunk = min(4, self.num_classes - c_idx)
            blocks.append((c_idx, chunk))
            c_idx += chunk
        mem_decls = []
        syn_reg_decls = []
        mem_reads = []
        mem_inits = []
        syn_wires = []
        for b_idx, (start_c, count) in enumerate(blocks):
            width = count * 9
            mem_decls.append(f'    (* ram_style = "block" *) reg [{width - 1}:0] syn_mem_blk_{b_idx} [0:NUM_INPUTS-1];')
            syn_reg_decls.append(f'    reg [{width - 1}:0] syn_data_blk_{b_idx};')
            mem_reads.append(f'        syn_data_blk_{b_idx} <= syn_mem_blk_{b_idx}[acc_addr];')
            for i in range(self.num_inputs):
                val_num = 0
                for sub_c in range(count):
                    w = int(self.weights[start_c + sub_c][i])
                    w_9b = w & 511
                    val_num |= w_9b << sub_c * 9
                hex_digits = (width + 3) // 4
                mem_inits.append(f"        syn_mem_blk_{b_idx}[{i}] = {width}'h{val_num:0{hex_digits}X};")
            for sub_c in range(count):
                c = start_c + sub_c
                offset = sub_c * 9
                syn_wires.append(f'    wire signed [9:0] syn_w_{c} = {{ {{1{{syn_data_blk_{b_idx}[{offset + 8}]}}}}, syn_data_blk_{b_idx}[{offset + 8} : {offset}] }};')
        mem_decls_str = '\n'.join(mem_decls)
        syn_reg_decls_str = '\n'.join(syn_reg_decls)
        mem_reads_str = '\n'.join(mem_reads)
        mem_inits_str = '\n'.join(mem_inits)
        syn_wires_str = '\n'.join(syn_wires)
        neuron_insts = []
        for c in range(self.num_classes):
            b_val = int(self.biases[c])
            b_str = f"10'sd{b_val}" if b_val >= 0 else f"-10'sd{abs(b_val)}"
            neuron_insts.append(f"        lif_neuron #(\n            .WIDTH(10),\n            .THRESHOLD(10'sd256)\n        ) u_lif_{c} (\n            .clk(clk),\n            .rst_n(rst_n),\n            .sim_start(sim_start),\n            .bias_val({b_str}),\n            .acc_step(acc_step),\n            .syn_weight(syn_w_{c}),\n            .ramp_step(sim_active),\n            .spike_out(spikes[{c}]),\n            .v_mem(v_mems[{c}])\n        );")
        neuron_insts_str = '\n'.join(neuron_insts)
        pe_lines = [f"        if (spikes[0]) winning_class = {self.class_width}'d0;"]
        for k in range(1, self.num_classes):
            pe_lines.append(f"        else if (spikes[{k}]) winning_class = {self.class_width}'d{k};")
        pe_lines.append(f"        else winning_class = {self.class_width}'d0;")
        pe_str = '\n'.join(pe_lines)
        code = f"`default_nettype none\n\n// Auto-generated Single-Layer SNN Core (BSRAM-Accelerated Crossbar)\n// Inputs: {self.num_inputs}, Classes: {self.num_classes}, Max TTFS Steps: {self.max_steps}\n\nmodule snn_core #(\n    parameter integer NUM_INPUTS   = {self.num_inputs},\n    parameter integer NUM_CLASSES  = {self.num_classes},\n    parameter signed [9:0] THRESHOLD = 10'sd{self.threshold},\n    parameter integer LEAK_SHIFT   = {self.leak_shift},\n    parameter integer MAX_STEPS    = {self.max_steps}\n)(\n    input  wire                    clk,\n    input  wire                    rst_n,\n    input  wire                    sim_start,\n    input  wire [NUM_INPUTS-1:0]   pixels,\n    output reg                     done,\n    output reg  [{self.class_width - 1}:0]       best_class,\n    output reg  [5:0]              ttfs_step\n);\n\n    // 1. Synaptic Weight Memory (Inferred into Gowin BSRAM)\n{mem_decls_str}\n{syn_reg_decls_str}\n    reg [{self.input_idx_width - 1}:0] acc_addr;\n\n    initial begin\n{mem_inits_str}\n    end\n\n    always @(posedge clk) begin\n{mem_reads_str}\n    end\n\n    // Synaptic Weight Slicers\n{syn_wires_str}\n\n    // 2. Control Pipeline\n    reg              acc_active;\n    reg              acc_valid;\n    reg              pixel_pipe;\n    reg              sim_active;\n\n    wire acc_step = acc_valid && pixel_pipe;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            acc_addr   <= {self.input_idx_width}'d0;\n            acc_active <= 1'b0;\n            acc_valid  <= 1'b0;\n            pixel_pipe <= 1'b0;\n            sim_active <= 1'b0;\n        end else begin\n            if (sim_start) begin\n                acc_addr   <= {self.input_idx_width}'d0;\n                acc_active <= 1'b1;\n                acc_valid  <= 1'b0;\n                pixel_pipe <= 1'b0;\n                sim_active <= 1'b0;\n            end else begin\n                if (acc_active) begin\n                    acc_valid  <= 1'b1;\n                    pixel_pipe <= pixels[acc_addr];\n                    if (acc_addr == {self.input_idx_width}'d{self.num_inputs - 1}) begin\n                        acc_active <= 1'b0;\n                    end else begin\n                        acc_addr <= acc_addr + 1'b1;\n                    end\n                end else begin\n                    acc_valid <= 1'b0;\n                    if (acc_valid) begin\n                        sim_active <= 1'b1;\n                    end\n                end\n\n                if (done) begin\n                    sim_active <= 1'b0;\n                end\n            end\n        end\n    end\n\n    // 3. Parallel LIF Neurons\n    wire [NUM_CLASSES-1:0] spikes;\n    wire signed [9:0]      v_mems [0:NUM_CLASSES-1];\n\n{neuron_insts_str}\n\n    // 4. Winner-Take-All / TTFS Arbiter\n    reg [5:0] step_cnt;\n    wire any_spike = |spikes;\n\n    reg [{self.class_width - 1}:0] winning_class;\n    always @(*) begin\n{pe_str}\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            step_cnt   <= 6'd0;\n            done       <= 1'b0;\n            best_class <= {self.class_width}'d0;\n            ttfs_step  <= 6'd0;\n        end else begin\n            done <= 1'b0;\n\n            if (sim_active && !done) begin\n                if (any_spike) begin\n                    done       <= 1'b1;\n                    ttfs_step  <= step_cnt;\n                    best_class <= winning_class;\n                    step_cnt   <= 6'd0;\n                end else if (step_cnt >= MAX_STEPS - 1) begin\n                    done       <= 1'b1;\n                    ttfs_step  <= step_cnt;\n                    best_class <= winning_class;\n                    step_cnt   <= 6'd0;\n                end else begin\n                    step_cnt <= step_cnt + 1'b1;\n                end\n            end else begin\n                step_cnt <= 6'd0;\n            end\n        end\n    end\n\nendmodule\n"
        return code
    def generate_top(self) -> str:
        if self.is_streaming:
            return self._generate_top_streaming()
        pixel_cnt_width = max(1, self.num_inputs.bit_length())
        extra_param = f',\n        .NUM_HIDDEN({self.num_hidden})' if self.is_hidden else ''
        code = f"""`default_nettype none\n\n// Auto-generated Top-level Module with UART Interface for Tang Nano 1K\n// Baud rate: 115200, Clock: 27 MHz\n\nmodule top #(\n    parameter CLK_FREQ = 27_000_000\n)(\n    input  wire       sys_clk,    // Pin 47\n    input  wire       sys_rst_n,  // Pin 13 (Key A)\n    input  wire       key_b,      // Pin 44 (Key B)\n    input  wire       uart_rx,    // Pin 40\n    output wire       uart_tx,    // Pin 41\n    output wire [2:0] led         // Pins 9, 10, 11 (active LOW)\n);\n\n    // 1. Power-on Reset\n    reg [7:0] por_cnt = 8'd0;\n    wire rst_n = (por_cnt == 8'd255);\n    always @(posedge sys_clk) begin\n        if (por_cnt < 8'd255)\n            por_cnt <= por_cnt + 1'b1;\n    end\n\n    // 2. UART Receiver\n    wire [7:0] rx_byte;\n    wire       rx_valid;\n\n    uart_rx #(\n        .CLK_FREQ(CLK_FREQ),\n        .BAUD_RATE(115200)\n    ) u_uart_rx (\n        .clk(sys_clk),\n        .rst_n(rst_n),\n        .rx_pin(uart_rx),\n        .data_out(rx_byte),\n        .valid_out(rx_valid)\n    );\n\n    // 3. Dynamic Shift Register Buffer ({self.num_inputs} bits)\n    reg [{self.num_inputs - 1}:0] pixel_shift;\n    reg [{pixel_cnt_width}:0]   pixel_cnt;\n    reg                         snn_start;\n\n    always @(posedge sys_clk or negedge rst_n) begin\n        if (!rst_n) begin\n            pixel_shift <= {self.num_inputs}'d0;\n            pixel_cnt   <= {pixel_cnt_width + 1}'d0;\n            snn_start   <= 1'b0;\n        end else begin\n            snn_start <= 1'b0;\n\n            if (rx_valid) begin\n                if (rx_byte == "0" || rx_byte == "1") begin\n                    pixel_shift <= {{ (rx_byte == "1"), pixel_shift[{self.num_inputs - 1}:1] }};\n                    if (pixel_cnt == {pixel_cnt_width + 1}'d{self.num_inputs - 1}) begin\n                        snn_start <= 1'b1;\n                        pixel_cnt <= {pixel_cnt_width + 1}'d0;\n                    end else begin\n                        pixel_cnt <= pixel_cnt + 1'b1;\n                    end\n                end else if (rx_byte == 8'h0A || rx_byte == 8'h0D) begin\n                    pixel_cnt <= {pixel_cnt_width + 1}'d0;\n                end\n            end\n        end\n    end\n\n    // 4. SNN Core Instance\n    wire                          snn_done;\n    wire [{self.class_width - 1}:0] snn_class;\n    wire [5:0]                    snn_ttfs;\n\n    snn_core #(\n        .NUM_INPUTS({self.num_inputs}),\n        .NUM_CLASSES({self.num_classes}){extra_param},\n        .THRESHOLD(10'sd{self.threshold}),\n        .LEAK_SHIFT({self.leak_shift}),\n        .MAX_STEPS({self.max_steps})\n    ) u_snn (\n        .clk(sys_clk),\n        .rst_n(rst_n),\n        .sim_start(snn_start),\n        .pixels(pixel_shift),\n        .done(snn_done),\n        .best_class(snn_class),\n        .ttfs_step(snn_ttfs)\n    );\n\n    // 5. UART Transmitter ("Class: %d (TTFS: %02d)\\r\\n")\n    reg [4:0]  tx_idx;\n    reg [{self.class_width - 1}:0] saved_class;\n    reg [5:0]  saved_ttfs;\n    reg [7:0]  tx_char;\n    reg        tx_start;\n    reg        tx_sending;\n    wire       tx_busy;\n\n    reg [3:0] ttfs_tens;\n    reg [3:0] ttfs_units;\n    always @(*) begin\n        if (saved_ttfs >= 6'd30) begin\n            ttfs_tens  = 4'd3;\n            ttfs_units = saved_ttfs - 6'd30;\n        end else if (saved_ttfs >= 6'd20) begin\n            ttfs_tens  = 4'd2;\n            ttfs_units = saved_ttfs - 6'd20;\n        end else if (saved_ttfs >= 6'd10) begin\n            ttfs_tens  = 4'd1;\n            ttfs_units = saved_ttfs - 6'd10;\n        end else begin\n            ttfs_tens  = 4'd0;\n            ttfs_units = saved_ttfs[3:0];\n        end\n    end\n\n    always @(*) begin\n        case (tx_idx)\n            5'd0:  tx_char = "C";\n            5'd1:  tx_char = "l";\n            5'd2:  tx_char = "a";\n            5'd3:  tx_char = "s";\n            5'd4:  tx_char = "s";\n            5'd5:  tx_char = ":";\n            5'd6:  tx_char = " ";\n            5'd7:  tx_char = 8'd48 + {{ 4'd0, saved_class }};\n            5'd8:  tx_char = " ";\n            5'd9:  tx_char = "(";\n            5'd10: tx_char = "T";\n            5'd11: tx_char = "T";\n            5'd12: tx_char = "F";\n            5'd13: tx_char = "S";\n            5'd14: tx_char = ":";\n            5'd15: tx_char = " ";\n            5'd16: tx_char = 8'd48 + {{ 4'd0, ttfs_tens }};\n            5'd17: tx_char = 8'd48 + {{ 4'd0, ttfs_units }};\n            5'd18: tx_char = ")";\n            5'd19: tx_char = 8'h0D;\n            5'd20: tx_char = 8'h0A;\n            default: tx_char = 8'd0;\n        endcase\n    end\n\n    reg [7:0] tx_data_reg;\n\n    always @(posedge sys_clk or negedge rst_n) begin\n        if (!rst_n) begin\n            tx_idx      <= 5'd0;\n            tx_start    <= 1'b0;\n            tx_sending  <= 1'b0;\n            saved_class <= {self.class_width}'d0;\n            saved_ttfs  <= 6'd0;\n            tx_data_reg <= 8'd0;\n        end else begin\n            tx_start <= 1'b0;\n\n            if (snn_done) begin\n                saved_class <= snn_class;\n                saved_ttfs  <= snn_ttfs;\n                tx_idx      <= 5'd0;\n                tx_sending  <= 1'b1;\n            end else if (tx_sending) begin\n                if (!tx_busy && !tx_start) begin\n                    if (tx_idx < 5'd21) begin\n                        tx_data_reg <= tx_char;\n                        tx_start    <= 1'b1;\n                        tx_idx      <= tx_idx + 1'b1;\n                    end else begin\n                        tx_sending <= 1'b0;\n                    end\n                end\n            end\n        end\n    end\n\n    uart_tx #(\n        .CLK_FREQ(CLK_FREQ),\n        .BAUD_RATE(115200)\n    ) u_uart_tx (\n        .clk(sys_clk),\n        .rst_n(rst_n),\n        .tx_data(tx_data_reg),\n        .tx_start(tx_start),\n        .tx_pin(uart_tx),\n        .tx_busy(tx_busy)\n    );\n\n    // 6. Visual Diagnostics (Active-Low LEDs)\n    assign led[0] = ~saved_class[0];\n    assign led[1] = (self_classes_gt_1) ? ~saved_class[1] : 1'b1;\n    assign led[2] = (self_classes_gt_2) ? ~saved_class[2] : 1'b1;\n\nendmodule\n""".replace('(self_classes_gt_1)', "1'b1" if self.num_classes > 1 else "1'b0").replace('(self_classes_gt_2)', "1'b1" if self.num_classes > 2 else "1'b0")
        return code
    def _generate_top_streaming(self) -> str:
        inits = [[] for _ in range(4)]
        for i in range(self.num_inputs):
            val0 = int(self.weights_l1[0][i]) & 63 | (int(self.weights_l1[1][i]) & 63) << 6 | (int(self.weights_l1[2][i]) & 63) << 12
            inits[0].append(f"        syn_mem_0[{i}] = 18'h{val0:05X};")
            val1 = int(self.weights_l1[3][i]) & 63 | (int(self.weights_l1[4][i]) & 63) << 6 | (int(self.weights_l1[5][i]) & 63) << 12
            inits[1].append(f"        syn_mem_1[{i}] = 18'h{val1:05X};")
            val2 = int(self.weights_l1[6][i]) & 63 | (int(self.weights_l1[7][i]) & 63) << 6 | (int(self.weights_l1[8][i]) & 63) << 12
            inits[2].append(f"        syn_mem_2[{i}] = 18'h{val2:05X};")
            val3 = int(self.weights_l1[9][i]) & 63 | (int(self.weights_l1[10][i]) & 63) << 6 | (int(self.weights_l1[11][i]) & 63) << 12
            inits[3].append(f"        syn_mem_3[{i}] = 18'h{val3:05X};")
        for j in range(self.num_hidden):
            row = self.num_inputs + j
            v0 = int(self.weights_l2[0][j]) & 63 | (int(self.weights_l2[1][j]) & 63) << 6 | (int(self.weights_l2[2][j]) & 63) << 12
            inits[0].append(f"        syn_mem_0[{row}] = 18'h{v0:05X};")
            v1 = int(self.weights_l2[3][j]) & 63 | (int(self.weights_l2[4][j]) & 63) << 6 | (int(self.weights_l2[5][j]) & 63) << 12
            inits[1].append(f"        syn_mem_1[{row}] = 18'h{v1:05X};")
            v2 = int(self.weights_l2[6][j]) & 63 | (int(self.weights_l2[7][j]) & 63) << 6 | (int(self.weights_l2[8][j]) & 63) << 12
            inits[2].append(f"        syn_mem_2[{row}] = 18'h{v2:05X};")
            v3 = int(self.weights_l2[9][j]) & 63
            inits[3].append(f"        syn_mem_3[{row}] = 18'h{v3:05X};")
        inits_str = '\n'.join(inits[0] + inits[1] + inits[2] + inits[3])
        b1_loads = []
        for k in range(self.num_hidden):
            val = int(self.biases_l1[k])
            b_str = f"-10'sd{abs(val)}" if val < 0 else f"10'sd{val}"
            b1_loads.append(f'                v_mem[{k}] <= {b_str};')
        b1_str = '\n'.join(b1_loads)
        b2_loads = []
        for c in range(self.num_classes):
            val = int(self.biases_l2[c])
            b_str = f"-10'sd{abs(val)}" if val < 0 else f"10'sd{val}"
            b2_loads.append(f'                    v_mem[{c}] <= {b_str};')
        b2_str = '\n'.join(b2_loads)
        code = f"""`default_nettype none\n\n// Auto-generated On-The-Fly Streaming SNN Top Module for Tang Nano 1K\n// Inputs: {self.num_inputs} (28x28), Hidden: {self.num_hidden}, Classes: {self.num_classes}\n// BSRAM Blocks: 4 (each 1024 x 18 bits), Clock: 27 MHz, Baud: 115200\n\nmodule top #(\n    parameter CLK_FREQ = 27_000_000\n)(\n    input  wire       sys_clk,    // Pin 47\n    input  wire       sys_rst_n,  // Pin 13\n    input  wire       key_b,      // Pin 44\n    input  wire       uart_rx,    // Pin 40\n    output wire       uart_tx,    // Pin 41\n    output wire [2:0] led         // Pins 9, 10, 11\n);\n\n    reg [7:0] por = 8'd0;\n    wire rst_n = (por == 8'd255);\n    always @(posedge sys_clk) if (por < 8'd255) por <= por + 1'b1;\n\n    wire [7:0] rx_byte;\n    wire       rx_valid;\n    uart_rx #(.CLK_FREQ(CLK_FREQ), .BAUD_RATE(115200)) u_rx (\n        .clk(sys_clk), .rst_n(rst_n), .rx_pin(uart_rx), .data_out(rx_byte), .valid_out(rx_valid)\n    );\n\n    // 4 Gowin BSRAM blocks (1024 x 18 bits)\n    (* ram_style = "block" *) reg [17:0] syn_mem_0 [0:1023];\n    (* ram_style = "block" *) reg [17:0] syn_mem_1 [0:1023];\n    (* ram_style = "block" *) reg [17:0] syn_mem_2 [0:1023];\n    (* ram_style = "block" *) reg [17:0] syn_mem_3 [0:1023];\n\n    reg [9:0]  mem_addr;\n    reg [17:0] syn_r0, syn_r1, syn_r2, syn_r3;\n\n    initial begin\n{inits_str}\n    end\n\n    always @(posedge sys_clk) begin\n        syn_r0 <= syn_mem_0[mem_addr];\n        syn_r1 <= syn_mem_1[mem_addr];\n        syn_r2 <= syn_mem_2[mem_addr];\n        syn_r3 <= syn_mem_3[mem_addr];\n    end\n\n    // Layer 1 weights (12 hidden neurons, signed 6-bit sign-extended to 10-bit)\n    wire signed [9:0] w_h [0:11];\n    assign w_h[0]  = {{{{4{{syn_r0[5]}}}},  syn_r0[5:0]}};\n    assign w_h[1]  = {{{{4{{syn_r0[11]}}}}, syn_r0[11:6]}};\n    assign w_h[2]  = {{{{4{{syn_r0[17]}}}}, syn_r0[17:12]}};\n    assign w_h[3]  = {{{{4{{syn_r1[5]}}}},  syn_r1[5:0]}};\n    assign w_h[4]  = {{{{4{{syn_r1[11]}}}}, syn_r1[11:6]}};\n    assign w_h[5]  = {{{{4{{syn_r1[17]}}}}, syn_r1[17:12]}};\n    assign w_h[6]  = {{{{4{{syn_r2[5]}}}},  syn_r2[5:0]}};\n    assign w_h[7]  = {{{{4{{syn_r2[11]}}}}, syn_r2[11:6]}};\n    assign w_h[8]  = {{{{4{{syn_r2[17]}}}}, syn_r2[17:12]}};\n    assign w_h[9]  = {{{{4{{syn_r3[5]}}}},  syn_r3[5:0]}};\n    assign w_h[10] = {{{{4{{syn_r3[11]}}}}, syn_r3[11:6]}};\n    assign w_h[11] = {{{{4{{syn_r3[17]}}}}, syn_r3[17:12]}};\n\n    // Layer 2 weights (10 classes, signed 6-bit sign-extended to 10-bit)\n    wire signed [9:0] w_o [0:9];\n    assign w_o[0]  = {{{{4{{syn_r0[5]}}}},  syn_r0[5:0]}};\n    assign w_o[1]  = {{{{4{{syn_r0[11]}}}}, syn_r0[11:6]}};\n    assign w_o[2]  = {{{{4{{syn_r0[17]}}}}, syn_r0[17:12]}};\n    assign w_o[3]  = {{{{4{{syn_r1[5]}}}},  syn_r1[5:0]}};\n    assign w_o[4]  = {{{{4{{syn_r1[11]}}}}, syn_r1[11:6]}};\n    assign w_o[5]  = {{{{4{{syn_r1[17]}}}}, syn_r1[17:12]}};\n    assign w_o[6]  = {{{{4{{syn_r2[5]}}}},  syn_r2[5:0]}};\n    assign w_o[7]  = {{{{4{{syn_r2[11]}}}}, syn_r2[11:6]}};\n    assign w_o[8]  = {{{{4{{syn_r2[17]}}}}, syn_r2[17:12]}};\n    assign w_o[9]  = {{{{4{{syn_r3[5]}}}},  syn_r3[5:0]}};\n\n    // Neuromorphic registers\n    reg signed [9:0] v_mem [0:11];\n    reg [11:0]       h_spikes;\n\n    reg [9:0] pixel_cnt;\n    reg [2:0] state;\n    reg [5:0] ramp_cnt;\n    reg [3:0] best_class;\n    reg [5:0] saved_ttfs;\n    reg [3:0] l2_idx;\n\n    // Output threshold detection: v >= 256\n    wire [9:0] out_spikes;\n    genvar g;\n    generate\n        for (g = 0; g < 10; g = g + 1) begin : gen_out_spikes\n            assign out_spikes[g] = (~v_mem[g][9]) & v_mem[g][8];\n        end\n    endgenerate\n\n    reg [3:0] pe_class;\n    always @(*) begin\n        if (out_spikes[0]) pe_class = 4'd0;\n        else if (out_spikes[1]) pe_class = 4'd1;\n        else if (out_spikes[2]) pe_class = 4'd2;\n        else if (out_spikes[3]) pe_class = 4'd3;\n        else if (out_spikes[4]) pe_class = 4'd4;\n        else if (out_spikes[5]) pe_class = 4'd5;\n        else if (out_spikes[6]) pe_class = 4'd6;\n        else if (out_spikes[7]) pe_class = 4'd7;\n        else if (out_spikes[8]) pe_class = 4'd8;\n        else if (out_spikes[9]) pe_class = 4'd9;\n        else pe_class = 4'd0;\n    end\n\n    localparam ST_STREAM_RX = 3'd0;\n    localparam ST_WAIT_BRAM = 3'd1;\n    localparam ST_ACC_PIXEL = 3'd2;\n    localparam ST_SPIKE_L1  = 3'd3;\n    localparam ST_WAIT_L2   = 3'd4;\n    localparam ST_ACC_L2    = 3'd5;\n    localparam ST_RAMP      = 3'd6;\n    localparam ST_TX        = 3'd7;\n\n    // Formatted UART output state machine ("Class: %d (TTFS: %02d)\\r\\n")\n    reg [4:0]  tx_idx;\n    reg [7:0]  tx_char;\n    reg        tx_start;\n    reg        tx_sending;\n    wire       tx_busy;\n\n    reg [3:0] ttfs_tens;\n    reg [3:0] ttfs_units;\n    always @(*) begin\n        if (saved_ttfs >= 6'd30) begin\n            ttfs_tens  = 4'd3;\n            ttfs_units = saved_ttfs - 6'd30;\n        end else if (saved_ttfs >= 6'd20) begin\n            ttfs_tens  = 4'd2;\n            ttfs_units = saved_ttfs - 6'd20;\n        end else if (saved_ttfs >= 6'd10) begin\n            ttfs_tens  = 4'd1;\n            ttfs_units = saved_ttfs - 6'd10;\n        end else begin\n            ttfs_tens  = 4'd0;\n            ttfs_units = saved_ttfs[3:0];\n        end\n    end\n\n    always @(*) begin\n        case (tx_idx)\n            5'd0:  tx_char = "C";\n            5'd1:  tx_char = "l";\n            5'd2:  tx_char = "a";\n            5'd3:  tx_char = "s";\n            5'd4:  tx_char = "s";\n            5'd5:  tx_char = ":";\n            5'd6:  tx_char = " ";\n            5'd7:  tx_char = 8'd48 + {{ 4'd0, best_class }};\n            5'd8:  tx_char = " ";\n            5'd9:  tx_char = "(";\n            5'd10: tx_char = "T";\n            5'd11: tx_char = "T";\n            5'd12: tx_char = "F";\n            5'd13: tx_char = "S";\n            5'd14: tx_char = ":";\n            5'd15: tx_char = " ";\n            5'd16: tx_char = 8'd48 + {{ 4'd0, ttfs_tens }};\n            5'd17: tx_char = 8'd48 + {{ 4'd0, ttfs_units }};\n            5'd18: tx_char = ")";\n            5'd19: tx_char = 8'h0D;\n            5'd20: tx_char = 8'h0A;\n            default: tx_char = " ";\n        endcase\n    end\n\n    integer k;\n\n    always @(posedge sys_clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state      <= ST_STREAM_RX;\n            mem_addr   <= 10'd0;\n            pixel_cnt  <= 10'd0;\n            l2_idx     <= 4'd0;\n            ramp_cnt   <= 6'd0;\n            best_class <= 4'd0;\n            saved_ttfs <= 6'd0;\n            tx_start   <= 1'b0;\n            tx_sending <= 1'b0;\n            tx_idx     <= 5'd0;\n            h_spikes   <= 12'd0;\n{b1_str}\n        end else begin\n            tx_start <= 1'b0;\n\n            if (tx_sending) begin\n                if (!tx_busy && !tx_start) begin\n                    if (tx_idx == 5'd20) begin\n                        tx_sending <= 1'b0;\n                        state      <= ST_STREAM_RX;\n                        pixel_cnt  <= 10'd0;\n{b1_str}\n                    end else begin\n                        tx_idx   <= tx_idx + 1'b1;\n                        tx_start <= 1'b1;\n                    end\n                end\n            end else begin\n                case (state)\n                    ST_STREAM_RX: begin\n                        if (rx_valid) begin\n                            if (rx_byte == "0" || rx_byte == "1") begin\n                                mem_addr <= pixel_cnt;\n                                if (rx_byte == "1") begin\n                                    state <= ST_WAIT_BRAM;\n                                end else begin\n                                    if (pixel_cnt == 10'd783) begin\n                                        state <= ST_SPIKE_L1;\n                                        pixel_cnt <= 10'd0;\n                                    end else begin\n                                        pixel_cnt <= pixel_cnt + 1'b1;\n                                    end\n                                end\n                            end else if (rx_byte == 8'h0A || rx_byte == 8'h0D) begin\n                                if (pixel_cnt > 10'd0) begin\n                                    state <= ST_SPIKE_L1;\n                                    pixel_cnt <= 10'd0;\n                                end\n                            end\n                        end\n                    end\n\n                    ST_WAIT_BRAM: begin\n                        state <= ST_ACC_PIXEL;\n                    end\n\n                    ST_ACC_PIXEL: begin\n                        for (k = 0; k < 12; k = k + 1) begin\n                            v_mem[k] <= v_mem[k] + w_h[k];\n                        end\n                        if (pixel_cnt == 10'd783) begin\n                            state <= ST_SPIKE_L1;\n                            pixel_cnt <= 10'd0;\n                        end else begin\n                            pixel_cnt <= pixel_cnt + 1'b1;\n                            state <= ST_STREAM_RX;\n                        end\n                    end\n\n                    ST_SPIKE_L1: begin\n                        for (k = 0; k < 12; k = k + 1) begin\n                            h_spikes[k] <= ~v_mem[k][9];\n                        end\n{b2_str}\n                        mem_addr <= 10'd784;\n                        l2_idx   <= 4'd0;\n                        state    <= ST_WAIT_L2;\n                    end\n\n                    ST_WAIT_L2: begin\n                        state <= ST_ACC_L2;\n                    end\n\n                    ST_ACC_L2: begin\n                        if (h_spikes[l2_idx]) begin\n                            for (k = 0; k < 10; k = k + 1) begin\n                                v_mem[k] <= v_mem[k] + w_o[k];\n                            end\n                        end\n                        if (l2_idx == 4'd11) begin\n                            state    <= ST_RAMP;\n                            ramp_cnt <= 6'd0;\n                        end else begin\n                            l2_idx   <= l2_idx + 1'b1;\n                            mem_addr <= mem_addr + 1'b1;\n                            state    <= ST_WAIT_L2;\n                        end\n                    end\n\n                    ST_RAMP: begin\n                        for (k = 0; k < 10; k = k + 1) begin\n                            v_mem[k] <= v_mem[k] + 10'sd16;\n                        end\n                        if (|out_spikes) begin\n                            best_class <= pe_class;\n                            saved_ttfs <= ramp_cnt;\n                            state      <= ST_TX;\n                        end else if (ramp_cnt >= 6'd31) begin\n                            best_class <= pe_class;\n                            saved_ttfs <= 6'd31;\n                            state      <= ST_TX;\n                        end else begin\n                            ramp_cnt <= ramp_cnt + 1'b1;\n                        end\n                    end\n\n                    ST_TX: begin\n                        tx_sending <= 1'b1;\n                        tx_idx     <= 5'd0;\n                        tx_start   <= 1'b1;\n                    end\n                endcase\n            end\n        end\n    end\n\n    uart_tx #(.CLK_FREQ(CLK_FREQ), .BAUD_RATE(115200)) u_tx (\n        .clk(sys_clk), .rst_n(rst_n), .tx_data(tx_char), .tx_start(tx_start), .tx_pin(uart_tx), .tx_busy(tx_busy)\n    );\n\n    assign led = ~best_class[2:0];\n\nendmodule\n"""
        return code
